#!/usr/bin/env bash
set -Eeuo pipefail
wp_local() { "$LOCAL_WP_COMMAND" --path="$LOCAL_WP_ROOT" "$@"; }
local_wp_check() { wp_local core is-installed >/dev/null 2>&1 || die 3 'LocalWP WP-CLI cannot access the site. Run from Local Site Shell or set LOCAL_WP_COMMAND to a working wrapper.'; }
local_code_preflight() { PHASE=local-preflight; require_clean_tree; [ -d "$PROJECT_ROOT/theme/rentacar-venezia-v2" ] && [ -f "$PROJECT_ROOT/plugin/rentacar-core/rentacar-core.php" ] || die 3 'owned theme or plugin missing'; if [ -f "$PROJECT_ROOT/package-lock.json" ]; then (cd "$PROJECT_ROOT" && npm ci); elif [ -f "$PROJECT_ROOT/pnpm-lock.yaml" ] && command_exists pnpm; then (cd "$PROJECT_ROOT" && pnpm install --frozen-lockfile); else die 3 'a package-lock.json/npm ci or pnpm-lock.yaml/pnpm is required for repeatable dependency installation'; fi; (cd "$PROJECT_ROOT" && npm run check && npm run build && ./scripts/php-lint.sh && git diff --check) || die 3 'local build checks failed'; [ -f "$PROJECT_ROOT/theme/rentacar-venezia-v2/assets/dist/manifest.json" ] || die 3 'compiled assets missing'; local_wp_check; if [ "$SKIP_LOCAL_TESTS" -ne 1 ] && [ "$RUN_BROWSER_TESTS" -eq 1 ] && [ "$SKIP_BROWSER_TESTS" -ne 1 ]; then (cd "$PROJECT_ROOT" && npm run test:browser) || die 3 'local browser tests failed'; fi; }
local_cutover_preflight() { local_code_preflight; wp_local db export "$DEPLOY_RUNTIME/local-preflight.sql" --add-drop-table; rm -f "$DEPLOY_RUNTIME/local-preflight.sql"; }
local_media_preflight() { [ -d "$LOCAL_WP_ROOT/wp-content/uploads" ] || die 3 'LocalWP uploads directory missing'; }
record_local_metadata() { LOCAL_PREFIX=$(wp_local db prefix); LOCAL_HOME=$(wp_local option get home); LOCAL_DB=$(wp_local db query 'SELECT DATABASE()' --skip-column-names); }
